package com.grifplot.libros;
import android.net.Uri;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
final class OpenLibrarySearch {
 static class Hit {String id,title,author,license,pdf;Hit(String i,String t,String a,String l){id=i;title=t;author=a;license=l;}}
 interface Progress {void update(long bytes,long total);boolean cancelled();}
 static boolean allowedLicense(String value){try{URI u=new URI(value);String host=u.getHost(),p=u.getPath();return ("creativecommons.org".equalsIgnoreCase(host)||"www.creativecommons.org".equalsIgnoreCase(host))&&p!=null&&(p.startsWith("/publicdomain/zero/")||p.startsWith("/publicdomain/mark/")||p.matches("/licenses/(by|by-sa)/[0-9.]+/?.*"));}catch(Exception e){return false;}}
 static String str(Object o){if(o instanceof JSONArray){JSONArray a=(JSONArray)o;ArrayList<String>s=new ArrayList<>();for(int i=0;i<a.length();i++)s.add(a.optString(i));return String.join(", ",s);}return o==null?"":String.valueOf(o);}
 static String license(Object o){if(o instanceof JSONArray){JSONArray arr=(JSONArray)o;for(int i=0;i<arr.length();i++)if(allowedLicense(arr.optString(i)))return arr.optString(i);return "";}String s=str(o);return allowedLicense(s)?s:"";}
 static HttpURLConnection connect(String url)throws Exception{String target=url;for(int i=0;i<6;i++){URL u=new URL(target);if(!u.getProtocol().equals("https"))throw new IOException("El enlace no es HTTPS");HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(12000);c.setReadTimeout(20000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Grifplotlibros/1.0 (+Android; open-license PDF reader)");int code=c.getResponseCode();if(code>=300&&code<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException("Redirección no válida");target=new URL(u,location).toString();continue;}if(code==401||code==403){c.disconnect();throw new IOException("Este enlace requiere acceso o no permite descargar");}if(code<200||code>=300){c.disconnect();throw new IOException("La fuente respondió con un error ("+code+")");}return c;}throw new IOException("Demasiadas redirecciones");}
 static JSONObject json(String url)throws Exception{HttpURLConnection c=connect(url);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()>10*1024*1024)throw new IOException("Respuesta demasiado grande");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}}
 static ArrayList<Hit> search(String query)throws Exception{String safe=SearchCore.norm(query).replace('"',' ');if(safe.isEmpty())throw new IOException("Escribe un título, autor o palabra clave");String q="mediatype:texts AND (format:\"Text PDF\" OR format:\"Image Container PDF\" OR format:PDF) AND licenseurl:(*creativecommons.org*) AND (title:(\""+safe+"\") OR creator:(\""+safe+"\") OR subject:(\""+safe+"\"))";JSONObject res=json("https://archive.org/advancedsearch.php?q="+Uri.encode(q)+"&fl[]=identifier&fl[]=title&fl[]=creator&fl[]=licenseurl&rows=40&page=1&output=json");JSONArray docs=res.getJSONObject("response").getJSONArray("docs");ArrayList<Hit> hits=new ArrayList<>();for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);String l=license(d.opt("licenseurl"));if(l.isEmpty())continue;hits.add(new Hit(d.getString("identifier"),str(d.opt("title")),str(d.opt("creator")),l));}return hits;}
 static void resolve(Hit h)throws Exception{JSONObject o=json("https://archive.org/metadata/"+Uri.encode(h.id));JSONObject m=o.getJSONObject("metadata");String l=license(m.opt("licenseurl"));if(l.isEmpty())throw new IOException("La fuente no indica una licencia abierta compatible");if(!m.optString("access-restricted-item").isEmpty()&&!m.optString("access-restricted-item").equals("false"))throw new IOException("Este libro requiere acceso");JSONArray fs=o.getJSONArray("files");String candidate="";for(int i=0;i<fs.length();i++){JSONObject f=fs.getJSONObject(i);String name=f.optString("name");if(!name.toLowerCase(Locale.ROOT).endsWith(".pdf")||f.optBoolean("private")||name.endsWith("_bw.pdf"))continue;candidate=name;if("original".equals(f.optString("source")))break;}if(candidate.isEmpty())throw new IOException("Esta fuente no ofrece un PDF público descargable");h.license=l;h.pdf="https://archive.org/download/"+Uri.encode(h.id)+"/"+Uri.encode(candidate);}
 static void download(Hit h,File tmp,Progress progress)throws Exception{resolve(h);HttpURLConnection c=connect(h.pdf);try(InputStream raw=c.getInputStream();BufferedInputStream in=new BufferedInputStream(raw);FileOutputStream out=new FileOutputStream(tmp)){long total=c.getContentLengthLong(),done=0;if(total>1024L*1024*1024)throw new IOException("El PDF supera el límite de 1 GB");byte[] signature=new byte[5];int read=0,n;while(read<5&&(n=in.read(signature,read,5-read))>0)read+=n;if(read!=5||!new String(signature,"US-ASCII").equals("%PDF-"))throw new IOException("El enlace no contiene un PDF válido");out.write(signature);done=5;byte[] b=new byte[65536];long last=0;while((n=in.read(b))!=-1){if(progress.cancelled())throw new IOException("Descarga cancelada");done+=n;if(done>1024L*1024*1024)throw new IOException("El PDF supera el límite de 1 GB");out.write(b,0,n);if(System.currentTimeMillis()-last>250){progress.update(done,total);last=System.currentTimeMillis();}}out.getFD().sync();progress.update(done,total);}finally{c.disconnect();}}
}
